/* MODULE kh04 · Bước 2 Hiểu khách hàng · Insight: sự thật chưa ai nói ra
   9 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kh04', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kh04-01', skill:'insight', read:'6 phút', t:'"Khách mua vào buổi tối" là insight hay chỉ là dữ kiện?',
  situation:'Bạn làm marketing cho một chuỗi bánh mì que ở Hải Phòng. Buổi họp đầu tuần, anh trưởng nhóm đưa ra "insight": khách mua nhiều nhất từ 5 đến 7 giờ tối. Chị bán hàng kể thêm: nhiều người mua hai túi, một túi ăn trên xe, một túi mang về. Sếp yêu cầu viết brief quảng cáo dựa trên "insight" đó trước thứ Sáu.',
  concept:{ name:'Bậc thang dữ kiện → quan sát → insight',
    body:'<b>Dữ kiện</b> là con số đo được: giờ mua, số túi. <b>Quan sát</b> là hành vi bạn thấy lặp lại: mua hai túi, ăn một túi ngay trên xe. <b>Insight</b> là lời giải thích vì sao họ làm vậy — một động cơ mà chính khách nhận ra khi nghe nhưng chưa từng nói thành lời. Dữ kiện trả lời "cái gì", quan sát trả lời "như thế nào", insight trả lời "vì sao". Chỉ bậc thứ ba mới đủ để viết một thông điệp chạm được người mua.' },
  example:'Giờ cao điểm buổi tối là dữ kiện. Mua hai túi, ăn một túi trên xe là quan sát. Hỏi thêm vài khách, bạn nghe: "Đói lả sau giờ làm, nhưng về nhà mà ăn vặt trước mặt con thì kỳ." Insight: người đi làm muốn được tự thưởng một chút riêng tư trước khi quay lại vai bố mẹ. Brief lúc này có hướng rõ: "Mười phút của riêng bạn trên đường về", thay vì một câu chung chung về giờ mở cửa.',
  takeaway:'Dữ kiện nói cái gì, quan sát nói thế nào, insight nói vì sao — brief chỉ viết được từ bậc thứ ba.',
  apply:'Lấy một con số bán hàng bạn biết. Trong 60 giây, nói ra một quan sát đi kèm và một câu "vì sao" mà khách sẽ gật đầu.',
  mistakes:['Gọi một con số trong báo cáo là insight.','Dừng ở quan sát hành vi mà không hỏi động cơ đằng sau.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: câu "khách mua nhiều nhất từ 5 đến 7 giờ tối" thuộc loại nào?',
    options:[{k:'a',t:'Insight, vì nó giúp chọn khung giờ chạy quảng cáo hiệu quả'},{k:'b',t:'Dữ kiện: đo được, nhưng chưa nói vì sao khách mua'},
             {k:'c',t:'Quan sát, vì nó mô tả hành vi mua lặp lại của nhiều khách'},{k:'d',t:'Giả thuyết, cần chạy thử nghiệm A/B trước khi tin'}],
    answer:'b', why:{a:'Hữu ích cho việc xếp lịch chạy, nhưng hữu ích chưa làm nó thành insight; nó không nói động cơ.',
      b:'Đúng. Đây là con số đo từ máy tính tiền — bậc thấp nhất của bậc thang.',
      c:'Quan sát là hành vi cụ thể bạn thấy (mua hai túi, ăn trên xe); giờ mua chỉ là số liệu tổng hợp.',
      d:'Nó đã được đo, nên không còn là giả thuyết; điều chưa có là lời giải thích.'} },
  { type:'mcq', stem:'Sếp muốn brief dựa trên giờ cao điểm. Bạn chọn làm gì trước khi viết brief?',
    options:[{k:'a',t:'Viết ngay brief "Mở cửa đến 9 giờ tối" để kịp hạn thứ Sáu'},{k:'b',t:'Chạy khảo sát 500 khách về khung giờ họ thích mua bánh nhất'},
             {k:'c',t:'Hỏi chuyện vài khách mua hai túi: vì sao ăn một túi ngay trên xe'},{k:'d',t:'Tăng ngân sách quảng cáo vào khung 5–7 giờ tối cho chắc ăn'}],
    answer:'c', why:{a:'Brief này chỉ nhắc lại dữ kiện; không có lý do để khách mới ghé.',
      b:'Khảo sát khung giờ lại cho thêm dữ kiện cùng loại, không mở được động cơ.',
      c:'Đúng. Quan sát lạ (hai túi, ăn trên xe) là cửa vào insight; vài cuộc hỏi chuyện là đủ để thấy "vì sao".',
      d:'Đây là quyết định phân bổ ngân sách, không phải thông điệp; brief vẫn trống.'} },
  { type:'mcq', stem:'Câu nào dưới đây là insight, không phải dữ kiện hay quan sát?',
    options:[{k:'a',t:'68% khách là nhân viên văn phòng từ 25 đến 40 tuổi'},{k:'b',t:'Khách thường đứng xem bánh khoảng hai phút trước khi chọn'},
             {k:'c',t:'Khách thích bánh giòn, nóng và được gói trong túi giấy cẩn thận'},{k:'d',t:'Họ muốn một khoảng riêng ngắn trước khi về làm bố mẹ'}],
    answer:'d', why:{a:'Chân dung nhân khẩu học là dữ kiện.',
      b:'Thời gian đứng chọn là quan sát hành vi.',
      c:'Đây là sở thích sản phẩm — nói ra ai cũng biết, không giải thích được hành vi lạ.',
      d:'Đúng. Nó giải thích vì sao khách mua hai túi và ăn một túi trên đường về.'} },
  { type:'mcq', stem:'Một hãng sữa hạt thấy 40% đơn online được đặt lúc 11 giờ đêm. Bước tiếp theo đúng thứ tự bậc thang là gì?',
    options:[{k:'a',t:'Kết luận ngay: khách hay mất ngủ nên cần sữa hạt giúp ngủ ngon'},{k:'b',t:'Tìm quan sát: ai đặt, đặt kèm gì, đang làm gì lúc đó'},
             {k:'c',t:'Chạy ngay quảng cáo khung 11 giờ đêm để đón đúng lượng đơn'},{k:'d',t:'Bỏ qua con số vì đơn đêm thường là đơn ảo và dễ bị huỷ'}],
    answer:'b', why:{a:'Nhảy thẳng từ số sang "insight" là đoán; có thể họ là mẹ bỉm đặt sau khi con ngủ.',
      b:'Đúng. Từ dữ kiện phải đi qua quan sát hành vi trước, rồi mới hỏi vì sao.',
      c:'Tối ưu giờ chạy dùng được dữ kiện, nhưng bỏ lỡ lý do có thể đổi cả thông điệp.',
      d:'Không có căn cứ nào cho thấy đơn đêm là đơn ảo; bỏ qua là mất manh mối.'} },
  { type:'mcq', stem:'Vì sao insight phải là điều khách "nhận ra khi nghe nhưng chưa nói thành lời"?',
    options:[{k:'a',t:'Vì điều khách đã tự nói ra thì đối thủ cũng đã nghe và đã dùng'},{k:'b',t:'Vì khách thường nói dối khi được hỏi trực tiếp trong phỏng vấn'},
             {k:'c',t:'Vì câu chưa nói ra nghe lạ hơn nên quảng cáo sẽ viral hơn'},{k:'d',t:'Vì pháp luật cấm quảng cáo dùng lời khách nói nguyên văn'}],
    answer:'a', why:{a:'Đúng. Điều ai cũng nói là tài sản chung; điều chưa nói ra mới cho bạn góc nhìn riêng mà khách vẫn thấy mình trong đó.',
      b:'Khách không nhất thiết nói dối; họ chỉ chưa từng nghĩ tới động cơ của mình.',
      c:'Lạ không đủ — khách phải nhận ra mình, nếu không thì chỉ là lạ.',
      d:'Không có quy định như vậy; lời khách thật còn được dùng nhiều trong quảng cáo.'} },
  { type:'mcq', stem:'Chị bán hàng kể: "Khách hay hỏi có bánh nhỏ hơn không." Đây là gì và nên xử lý ra sao?',
    options:[{k:'a',t:'Insight rõ ràng: khách muốn bánh nhỏ, cần ra mắt size mini ngay'},{k:'b',t:'Dữ kiện ít giá trị, vì chỉ một nhân viên kể lại theo trí nhớ'},
             {k:'c',t:'Quan sát; cần hỏi vì sao họ muốn bánh nhỏ trước khi kết luận'},{k:'d',t:'Lời phàn nàn về giá, nên giảm giá túi thường là giải quyết xong'}],
    answer:'c', why:{a:'Lời yêu cầu của khách chưa phải động cơ; có thể họ muốn nhỏ vì ăn trên xe, vì ngại con thấy, hay vì đang ăn kiêng.',
      b:'Lời kể lặp lại của người đứng quầy là quan sát quý, không nên bỏ.',
      c:'Đúng. Đó là hành vi lặp lại — bậc hai. Hỏi "vì sao" mới biết nên làm size mini hay đổi thông điệp.',
      d:'Không có dấu hiệu nào về giá; suy diễn sang giảm giá là bỏ qua động cơ thật.'} },
  { type:'mcq', stem:'Brief nào cho thấy người viết đã đi tới bậc insight?',
    options:[{k:'a',t:'"Bánh giòn nóng, mở cửa từ 6 giờ sáng tới tận 9 giờ tối"'},{k:'b',t:'"Nhắm nhân viên văn phòng 25–40 tuổi, chạy khung 5–7 giờ tối"'},
             {k:'c',t:'"Khách mua hai túi; hãy làm combo hai túi có giảm giá"'},{k:'d',t:'"Mười phút của riêng bạn trên đường về nhà"'}],
    answer:'d', why:{a:'Chỉ là thuộc tính sản phẩm và giờ mở cửa.',
      b:'Đây là cách nhắm đối tượng dựa trên dữ kiện, chưa có lý do mua.',
      c:'Phản ứng trực tiếp với quan sát, bỏ qua vì sao họ ăn một túi ngay trên xe.',
      d:'Đúng. Câu này nói tới động cơ — khoảng riêng trước khi về vai bố mẹ.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kh04-02', skill:'insight', read:'7 phút', t:'Vì sao "mẹ muốn con khoẻ" không phải là insight?',
  situation:'Một hãng sữa bột mới vào thị trường Việt Nam gửi agency brief với "insight": mẹ nào cũng muốn con khoẻ mạnh, thông minh. Agency trả về ba concept, cả ba đều là em bé chạy nhảy, cười tươi, kèm chữ "phát triển toàn diện". Nhóm thương hiệu thấy chúng giống hệt quảng cáo của mấy hãng đang dẫn đầu.',
  concept:{ name:'Insight là một căng thẳng',
    body:'Một câu ai cũng đồng ý thì không mở ra được gì — nó là <b>điều hiển nhiên</b>. Insight tốt thường có dạng căng thẳng: <b>"Tôi muốn A, nhưng B"</b>. Phần "muốn" là mong muốn chung; phần "nhưng" là rào cản, nỗi sợ hay mâu thuẫn khiến họ khó xử. Chính chỗ vướng đó là nơi thương hiệu có vai trò: gỡ nó, hoặc nói hộ nó. Nếu câu của bạn không có chữ "nhưng", hãy nghi ngờ.' },
  example:'"Mẹ muốn con khoẻ" đúng với mọi hãng nên không phân biệt ai. Nghe mẹ nói chuyện trong nhóm Facebook, bạn thấy một vướng mắc: "Tôi muốn con ăn đủ chất, nhưng mỗi bữa là một cuộc chiến và tôi thấy mình là người mẹ thất bại khi con bỏ dở." Căng thẳng này mở hướng mới: thương hiệu có thể nói "bữa ăn không phải bài kiểm tra làm mẹ", hoặc làm sản phẩm giúp bữa ăn bớt căng. Ba concept em bé cười tươi không còn là lựa chọn duy nhất.',
  takeaway:'Nếu câu insight không có chữ "nhưng", có lẽ bạn mới chỉ viết ra điều ai cũng biết.',
  apply:'Viết một câu "Tôi muốn…, nhưng…" cho khách hàng của sản phẩm bạn đang theo. Đọc to và hỏi: phần "nhưng" có thật sự làm họ khó xử không?',
  mistakes:['Viết insight là một mong muốn chung mà mọi hãng đều nói.','Phần "nhưng" là lời than về giá thay vì một mâu thuẫn thật.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vấn đề lớn nhất của câu "mẹ nào cũng muốn con khoẻ mạnh, thông minh" là gì?',
    options:[{k:'a',t:'Câu quá dài, cần rút gọn cho dễ nhớ khi truyền đạt cho agency'},{k:'b',t:'Nó sai, vì nhiều mẹ ngày nay ưu tiên con vui hơn con khoẻ'},
             {k:'c',t:'Nó đúng với mọi hãng nên không cho ra ý tưởng khác biệt'},{k:'d',t:'Nó nói về mẹ, trong khi người uống sữa thật sự là em bé'}],
    answer:'c', why:{a:'Độ dài không phải vấn đề; câu ngắn mà hiển nhiên vẫn vô dụng.',
      b:'Câu không sai — nó đúng tới mức vô dụng.',
      c:'Đúng. Điều hiển nhiên dẫn tới quảng cáo giống hệt đối thủ, như ba concept agency gửi.',
      d:'Người mua (mẹ) và người dùng (bé) khác nhau là chuyện có thật, nhưng không phải lỗi chính của câu này.'} },
  { type:'mcq', stem:'Ba concept đều giống quảng cáo đối thủ. Bạn làm gì tiếp?',
    options:[{k:'a',t:'Chọn concept đẹp nhất rồi tăng ngân sách để át đối thủ'},{k:'b',t:'Yêu cầu agency đổi màu, nhạc và diễn viên cho thật khác biệt'},
             {k:'c',t:'Giữ insight, thêm tính năng DHA vào thông điệp cho nổi bật hơn'},{k:'d',t:'Viết lại brief: tìm chỗ "muốn… nhưng…" mà mẹ đang vướng'}],
    answer:'d', why:{a:'Chi nhiều hơn cho một ý giống đối thủ là trả tiền quảng cáo hộ hãng dẫn đầu.',
      b:'Đổi hình thức không sửa được gốc: insight hiển nhiên thì mọi phương án sẽ na ná.',
      c:'Tính năng đối thủ cũng có; thêm vào vẫn đứng trên cùng một câu hiển nhiên.',
      d:'Đúng. Lỗi nằm ở brief; sửa insight thì concept mới có chỗ khác biệt.'} },
  { type:'mcq', stem:'Câu nào có cấu trúc căng thẳng của một insight?',
    options:[{k:'a',t:'"Tôi muốn con ăn đủ chất, nhưng bữa nào cũng là một cuộc chiến"'},{k:'b',t:'"Tôi muốn con ăn đủ chất và lớn nhanh như các bạn cùng lớp"'},
             {k:'c',t:'"Tôi muốn con ăn đủ chất, nhưng sữa ngoại thì giá hơi cao so với thu nhập"'},{k:'d',t:'"Các mẹ ngày càng quan tâm dinh dưỡng cho con nhỏ"'}],
    answer:'a', why:{a:'Đúng. Mong muốn và rào cản cảm xúc đối nghịch nhau, tạo chỗ cho thương hiệu can thiệp.',
      b:'Chỉ có mong muốn, không có vướng mắc.',
      c:'Có chữ "nhưng", song rào cản giá ai cũng biết và chỉ dẫn tới giảm giá.',
      d:'Đây là một xu hướng, không phải căng thẳng của một con người cụ thể.'} },
  { type:'mcq', stem:'Một hãng giày chạy bộ có insight: "Tôi muốn chạy đều, nhưng ngại người trong khu nhìn mình chạy chậm." Ý tưởng nào khai thác đúng căng thẳng?',
    options:[{k:'a',t:'Quảng cáo đế giày êm, giúp chạy nhanh hơn 10% sau một tháng'},{k:'b',t:'Nhóm chạy lúc 5 giờ sáng cho người mới, không ai tính tốc độ'},
             {k:'c',t:'Mời vận động viên marathon nổi tiếng làm gương mặt đại diện'},{k:'d',t:'Giảm giá 30% cho người mua đôi đầu tiên để thử chạy'}],
    answer:'b', why:{a:'Hứa chạy nhanh hơn né sang tính năng; nỗi ngại bị nhìn vẫn còn nguyên.',
      b:'Đúng. Gỡ đúng phần "nhưng": không bị so sánh, không bị nhìn.',
      c:'Vận động viên giỏi càng làm người mới thấy khoảng cách lớn hơn.',
      d:'Giá không phải rào cản trong câu insight này.'} },
  { type:'mcq', stem:'Vì sao phần "nhưng" là giá cả thường cho ra insight yếu?',
    options:[{k:'a',t:'Vì khách Việt Nam không bao giờ để ý tới giá khi mua hàng'},{k:'b',t:'Vì nói về giá bị coi là quảng cáo so sánh và bị cấm theo luật'},
             {k:'c',t:'Vì ai cũng biết, và lời giải duy nhất là giảm giá, ăn vào lãi'},{k:'d',t:'Vì giá là việc của phòng tài chính, không phải của marketer'}],
    answer:'c', why:{a:'Khách rất để ý giá; vấn đề là rào cản giá không riêng của ai.',
      b:'Nói về giá không phải quảng cáo so sánh; không có lệnh cấm như vậy.',
      c:'Đúng. Rào cản giá đúng với mọi ngành, không mở ra góc nhìn mới mà chỉ dẫn tới cuộc đua giảm giá.',
      d:'Marketer vẫn quyết định giá trong 4P; đó không phải lý do.'} },
  { type:'mcq', stem:'Nhóm bạn viết: "Sinh viên muốn tiết kiệm." Cách sửa nào đưa câu này gần insight nhất?',
    options:[{k:'a',t:'"Sinh viên muốn tiết kiệm, nhưng ngại bị bạn bè nghĩ là keo kiệt"'},{k:'b',t:'"Sinh viên muốn tiết kiệm 20% chi tiêu mỗi tháng từ học kỳ này"'},
             {k:'c',t:'"Sinh viên Hà Nội và TP.HCM rất muốn tiết kiệm tiền ăn uống"'},{k:'d',t:'"Sinh viên muốn tiết kiệm vì học phí ngày càng tăng mạnh"'}],
    answer:'a', why:{a:'Đúng. Có căng thẳng xã hội cụ thể — một chỗ thương hiệu có thể gỡ.',
      b:'Thêm con số làm câu cụ thể hơn nhưng vẫn là một mong muốn trơn.',
      c:'Thêm địa lý là phân khúc, không phải insight.',
      d:'Thêm nguyên nhân kinh tế mà ai cũng biết, không có vướng mắc cảm xúc.'} },
  { type:'mcq', stem:'Căng thẳng "muốn A nhưng B" hữu ích nhất cho thương hiệu ở điểm nào?',
    options:[{k:'a',t:'Giúp quảng cáo có kịch bản xung đột nên dễ làm phim hơn'},{k:'b',t:'Chỉ ra đúng chỗ thương hiệu có thể gỡ vướng hoặc nói hộ khách'},
             {k:'c',t:'Giúp đo lường chính xác hơn vì có hai biến số A và B để theo dõi'},{k:'d',t:'Giúp phân khúc khách thành hai nhóm: nhóm A và nhóm B'}],
    answer:'b', why:{a:'Xung đột giúp kể chuyện, nhưng đó là hệ quả, không phải lý do chính.',
      b:'Đúng. Phần "nhưng" là vai trò của thương hiệu trong đời khách.',
      c:'A và B là hai vế tâm lý, không phải chỉ số đo.',
      d:'Cùng một người mang cả hai vế; đó không phải hai phân khúc.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kh04-03', skill:'insight', read:'7 phút', t:'Làm sao biết insight của bạn đúng trước khi làm quảng cáo?',
  situation:'Một ví điện tử muốn kéo người trên 45 tuổi dùng chuyển tiền. Nhóm có hai câu insight và chỉ đủ ngân sách làm một phim. Thay vì bỏ phiếu trong phòng họp, bạn đọc từng câu cho 20 người trên 45 tuổi ở một khu chợ tại Biên Hoà rồi ghi lại phản ứng đầu tiên của họ.',
  concept:{ name:'Phép thử "đúng quá"',
    body:'Insight thật gây ra một phản ứng rất riêng khi khách nghe: họ bật cười, gật đầu, hoặc nói "<b>đúng quá</b>", "y như nhà tôi". Nếu phản ứng là "ừ, hợp lý", câu đó mới chỉ đúng về lý. Nếu là "hả, không phải đâu", câu đó sai. Phép thử không cần phim hay mẫu lớn: đọc nguyên văn câu, không giải thích, ghi lại phản ứng trong ba giây đầu. Cái bạn đo là tỉ lệ người nhận ra chính mình.' },
  example:'Câu 1: "Người lớn tuổi sợ chuyển nhầm tiền." Trong 20 người, 6 người gật đầu "đúng quá", phần lớn còn lại bảo "ừ, ai chả sợ". Câu 2: "Tôi muốn tự chuyển tiền cho con, nhưng ngại hỏi con mãi cách làm, sợ con nghĩ mình chậm." Có 14 người cười, gật, kể luôn chuyện nhà mình. Tỉ lệ "đúng quá" là 30% so với 70%. Câu 2 thắng rõ, và còn gợi ý phim: bố tự làm được mà không phải gọi con.',
  takeaway:'Đọc insight cho khách nghe: "đúng quá" là thật, "hợp lý" là chưa, "không phải" là sai.',
  apply:'Chọn một câu insight nhóm bạn đang dùng. Đọc nguyên văn cho 5 người trong tệp và ghi lại đúng phản ứng đầu tiên của mỗi người.',
  mistakes:['Giải thích thêm trước khi đọc, làm khách gật cho lịch sự.','Thử trên đồng nghiệp trong phòng họp thay vì người trong tệp khách.'],
  q:[
  { type:'mcq', stem:'Đoán trước: phản ứng nào của khách cho thấy một insight đang đúng?',
    options:[{k:'a',t:'Khách nói "câu này hợp lý, chắc nhiều người cũng thấy vậy"'},{k:'b',t:'Khách hỏi lại "vậy sản phẩm của các bạn giải quyết thế nào?"'},
             {k:'c',t:'Khách bật cười và nói "đúng quá, y như nhà tôi"'},{k:'d',t:'Khách đồng ý sau khi nghe bạn giải thích thêm lý do cặn kẽ'}],
    answer:'c', why:{a:'Đồng ý về lý nhưng không nhận ra mình — tín hiệu của câu hiển nhiên.',
      b:'Quan tâm sản phẩm là tốt, nhưng không cho biết câu insight có chạm họ không.',
      c:'Đúng. Nhận ra chính mình ngay lập tức là dấu hiệu của sự thật chưa ai nói.',
      d:'Đồng ý sau khi được giải thích là bị thuyết phục, không phải nhận ra.'} },
  { type:'mcq', stem:'Chỉ đủ tiền làm một phim, nhóm đang chia đôi giữa hai câu insight. Bạn chọn cách nào?',
    options:[{k:'a',t:'Để sếp quyết vì sếp có nhiều kinh nghiệm hơn cả nhóm cộng lại'},{k:'b',t:'Đọc nguyên văn hai câu cho khoảng 20 người trong tệp, đếm "đúng quá"'},
             {k:'c',t:'Làm hai phim ngắn giá rẻ rồi chạy thử cả hai trên mạng xã hội'},{k:'d',t:'Bỏ phiếu kín trong nhóm để tránh việc ai nói to thì thắng'}],
    answer:'b', why:{a:'Kinh nghiệm của sếp vẫn là ý kiến trong phòng họp, không phải phản ứng của khách.',
      b:'Đúng. Rẻ, nhanh, và đo đúng thứ cần đo: khách có nhận ra mình không.',
      c:'Làm hai phim tốn tiền sản xuất mà ngân sách không có; thử bằng lời đã đủ ở bước này.',
      d:'Bỏ phiếu kín vẫn là ý kiến của người làm marketing, không phải người dùng.'} },
  { type:'calc', stem:'Bạn đọc một câu insight cho 25 người trong tệp; 9 người phản ứng "đúng quá". Tỉ lệ "đúng quá" là bao nhiêu phần trăm?',
    unit:'%', ans:36, tol:0.5, wrong:[[9,'NHAM_SO_TUYET_DOI'],[27.8,'SAI_MAU_SO']], errors:['NHAM_SO_TUYET_DOI','SAI_MAU_SO'],
    steps:['Tỉ lệ = số người "đúng quá" ÷ tổng số người nghe.','9 ÷ 25 = 0,36 = <b>36%</b>.'] },
  { type:'calc', stem:'Câu A được 6/20 người phản ứng "đúng quá", câu B được 14/20. Câu B hơn câu A bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:40, tol:0.5, wrong:[[133.3,'NHAM_DIEM_PHAN_TRAM'],[8,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Câu A: 6 ÷ 20 = 30%. Câu B: 14 ÷ 20 = 70%.','Chênh lệch = 70% − 30% = <b>40 điểm phần trăm</b> (không phải "tăng 133%").'] },
  { type:'mcq', stem:'Khi thử, bạn nói trước: "Chúng tôi nghĩ người lớn tuổi hay ngại hỏi con, vì…" rồi mới đọc câu. Vấn đề là gì?',
    options:[{k:'a',t:'Lời dẫn dắt khiến khách gật đầu cho lịch sự, phản ứng không còn thật'},{k:'b',t:'Không vấn đề gì, vì giải thích giúp khách hiểu đúng ý câu hơn'},
             {k:'c',t:'Tốn thời gian của khách, nên mẫu thử sẽ nhỏ đi đáng kể'},{k:'d',t:'Khách sẽ nhớ câu và kể lại cho đối thủ trước khi phim lên sóng'}],
    answer:'a', why:{a:'Đúng. Phép thử đo phản ứng tự nhiên; mọi lời dẫn đều làm lệch kết quả về phía "đồng ý".',
      b:'Nếu câu cần giải thích mới hiểu, đó đã là dấu hiệu nó chưa chạm.',
      c:'Thời gian là chuyện phụ; lỗi chính là làm hỏng dữ liệu.',
      d:'Rủi ro lộ ý tưởng rất nhỏ so với rủi ro đo sai.'} },
  { type:'mcq', stem:'Một hãng mỹ phẩm thử insight trên 10 nhân viên nữ của công ty, 9 người nói "đúng quá". Nên đọc kết quả thế nào?',
    options:[{k:'a',t:'Rất tốt: 90% là con số quá đủ để tự tin làm phim ngay'},{k:'b',t:'Kết quả vẫn dùng được nếu nhân viên cùng độ tuổi với tệp khách'},
             {k:'c',t:'Nên tăng mẫu lên 50 nhân viên trong công ty để chắc chắn hơn'},{k:'d',t:'Chưa tin được: nhân viên hiểu thương hiệu và muốn đồng tình'}],
    answer:'d', why:{a:'90% trên người trong nhà chỉ đo sự đồng thuận nội bộ.',
      b:'Cùng tuổi chưa đủ; họ đã biết sản phẩm và có động cơ làm vui lòng công ty.',
      c:'Tăng mẫu vẫn lặp lại cùng một thiên lệch.',
      d:'Đúng. Phải thử trên người thật trong tệp, không biết mình đang được hỏi cho ai.'} },
  { type:'mcq', stem:'Khoảng một nửa người nghe nói "ừ, hợp lý", số ít nói "đúng quá". Bạn nên xử lý câu insight ra sao?',
    options:[{k:'a',t:'Giữ nguyên, vì đa số không phản đối câu đó thì nó vẫn dùng được'},{k:'b',t:'Bỏ hẳn hướng này và chuyển sang một nhóm khách hoàn toàn khác'},
             {k:'c',t:'Đào sâu thêm phần "nhưng" cho cụ thể hơn rồi thử lại'},{k:'d',t:'Giữ câu, bù lại bằng hình ảnh phim thật cảm động để chạm người xem'}],
    answer:'c', why:{a:'"Hợp lý" nghĩa là đúng về lý nhưng chưa chạm; phim sẽ bị lướt qua.',
      b:'Có số ít nhận ra mình nghĩa là có một mạch thật; bỏ hẳn là phí.',
      c:'Đúng. Phản ứng nửa vời thường do vế vướng mắc còn chung chung; làm cụ thể rồi thử lại.',
      d:'Hình ảnh không cứu được một ý mà khách không nhận ra mình trong đó.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kh04-04', skill:'creative', read:'7 phút', t:'Có insight rồi, làm sao ra được ý tưởng?',
  situation:'Một hãng nước mắm mới ở Phú Quốc có insight đã được thử: "Tôi muốn nấu cơm nhà cho con ăn, nhưng tối nào đi làm về cũng chỉ còn sức làm món rang, món kho." Nhóm sáng tạo đưa ra ý tưởng: phim hai phút về nghề làm nước mắm ba đời. Ai cũng khen đẹp, nhưng bạn thấy có gì đó lệch.',
  concept:{ name:'Cây cầu insight → vai trò thương hiệu → ý tưởng',
    body:'Insight không tự thành quảng cáo. Giữa hai thứ là một câu hỏi: <b>thương hiệu làm gì với căng thẳng này?</b> Có ba vai trò thường gặp: <b>gỡ</b> vướng (đưa ra cách làm dễ hơn), <b>đổi góc nhìn</b> (nói rằng điều khách lo không đáng lo), hoặc <b>đứng về phía khách</b> (nói hộ điều họ ngại nói). Chọn một vai trò, rồi ý tưởng mới xuất hiện. Ý tưởng không nối được về phần "nhưng" của insight là ý tưởng đẹp nhưng lạc.' },
  example:'Phim nghề ba đời nói về sản phẩm, không chạm phần "chỉ còn sức làm món rang, món kho". Thử ba vai trò. Gỡ: "Một thìa nước mắm, món rang thành món nhà" — loạt công thức ba bước mười phút. Đổi góc nhìn: "Món kho đơn giản cũng là cơm mẹ nấu", giải toả cảm giác có lỗi. Đứng về phía khách: phim ngắn người mẹ mệt vẫn vào bếp, không cần hoàn hảo. Cả ba đều bám vào vướng mắc; nhóm chọn "gỡ" vì hợp với một thương hiệu mới cần lý do dùng thử.',
  takeaway:'Trước khi nghĩ ý tưởng, trả lời: thương hiệu gỡ, đổi góc nhìn, hay đứng về phía khách?',
  apply:'Lấy câu insight của bạn. Viết ba dòng: một ý tưởng "gỡ", một "đổi góc nhìn", một "đứng về phía khách". Chọn một và nói lý do trong 60 giây.',
  mistakes:['Làm phim về sản phẩm rồi gắn insight vào lời dẫn cho có.','Chọn ý tưởng đẹp nhất thay vì ý tưởng bám vào phần "nhưng".'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao phim "nghề làm nước mắm ba đời" có thể lệch khỏi insight?',
    options:[{k:'a',t:'Phim hai phút quá dài, người xem mạng xã hội sẽ lướt qua'},{k:'b',t:'Nghề truyền thống đã quá nhiều hãng khai thác, không còn mới lạ'},
             {k:'c',t:'Nói về xuất xứ là sai luật quảng cáo thực phẩm hiện hành'},{k:'d',t:'Nó kể về sản phẩm, không chạm nỗi mệt lúc nấu cơm tối'}],
    answer:'d', why:{a:'Độ dài có thể là vấn đề, nhưng phim ngắn mà lạc vẫn lạc.',
      b:'Có thể đúng, nhưng lỗi gốc là không nối về insight đã thử.',
      c:'Nói xuất xứ thật không vi phạm luật.',
      d:'Đúng. Ý tưởng không đi qua phần "nhưng" thì insight chỉ còn nằm trên giấy.'} },
  { type:'mcq', stem:'Thương hiệu mới cần người dùng thử ngay. Bạn chọn vai trò nào cho ý tưởng?',
    options:[{k:'a',t:'Đứng về phía khách: phim cảm động về người mẹ mệt mỏi sau giờ làm'},{k:'b',t:'Gỡ vướng: công thức ba bước mười phút có dùng sản phẩm'},
             {k:'c',t:'Đổi góc nhìn: món kho đơn giản cũng là cơm mẹ nấu cho con'},{k:'d',t:'Kể nghề ba đời để xây uy tín trước, còn dùng thử tính sau'}],
    answer:'b', why:{a:'Chạm cảm xúc tốt nhưng không cho lý do cụ thể để mua chai đầu tiên.',
      b:'Đúng. "Gỡ" gắn sản phẩm vào hành động cụ thể, hợp với mục tiêu dùng thử.',
      c:'Hợp với thương hiệu đã lớn muốn gần gũi; hãng mới cần lý do dùng thử hơn.',
      d:'Uy tín quan trọng, nhưng không trả lời vướng mắc của khách.'} },
  { type:'mcq', stem:'Ý tưởng nào là "đổi góc nhìn" với insight "muốn con đọc sách, nhưng sợ con chán vì mình không biết chọn sách hay"?',
    options:[{k:'a',t:'"Cuốn sách hay nhất là cuốn con tự chọn" — cho con đi chọn'},{k:'b',t:'Hộp sách chọn sẵn theo tuổi, giao tận nhà hằng tháng'},
             {k:'c',t:'Phim kể nỗi lo thầm lặng của bố mẹ khi đứng trước giá sách'},{k:'d',t:'Giảm giá 20% cho đơn hàng sách thiếu nhi đầu tiên trên app'}],
    answer:'a', why:{a:'Đúng. Nó nói rằng nỗi lo "mình không biết chọn" không cần thiết.',
      b:'Đây là "gỡ" — đưa ra giải pháp chọn sách hộ.',
      c:'Đây là "đứng về phía khách" — nói hộ nỗi lo.',
      d:'Khuyến mãi không đụng tới căng thẳng nào trong insight.'} },
  { type:'mcq', stem:'Nhóm có năm ý tưởng. Tiêu chí lọc đầu tiên nên là gì?',
    options:[{k:'a',t:'Ý tưởng nào sếp và khách hàng thích nhất trong buổi họp'},{k:'b',t:'Ý tưởng nào rẻ nhất để sản xuất trong ngân sách hiện có'},
             {k:'c',t:'Ý tưởng có nối thẳng về phần "nhưng" của insight không'},{k:'d',t:'Ý tưởng nào có khả năng viral cao nhất trên TikTok'}],
    answer:'c', why:{a:'Thích trong phòng họp không đảm bảo chạm khách.',
      b:'Chi phí là tiêu chí sau; ý rẻ mà lạc vẫn lãng phí.',
      c:'Đúng. Lọc theo độ bám insight trước, rồi mới xét chi phí và kênh.',
      d:'Viral mà không nối về insight thì người xem nhớ clip, không nhớ lý do mua.'} },
  { type:'mcq', stem:'Một app học tiếng Anh có insight: "Tôi muốn nói tiếng Anh, nhưng sợ nói sai trước đồng nghiệp." Ý tưởng nào lạc?',
    options:[{k:'a',t:'Luyện nói với trợ lý ảo, không ai nghe thấy bạn nói sai'},{k:'b',t:'Chiến dịch "Nói sai mới là đang học" với người nổi tiếng kể lỗi'},
             {k:'c',t:'Quảng cáo kho 5.000 bài học từ vựng được thiết kế bởi giáo viên bản xứ'},{k:'d',t:'Phim ngắn về người ngại mở miệng trong cuộc họp tiếng Anh'}],
    answer:'c', why:{a:'Gỡ đúng nỗi sợ bị nghe thấy.',
      b:'Đổi góc nhìn: sai là bình thường.',
      c:'Đúng. Kho bài học là tính năng, không liên quan nỗi sợ nói sai trước người khác.',
      d:'Đứng về phía khách, nói hộ nỗi ngại.'} },
  { type:'mcq', stem:'Vì sao không nên chọn ý tưởng chỉ vì nó "đẹp"?',
    options:[{k:'a',t:'Vì đẹp tốn tiền hơn, khó xin duyệt ngân sách hơn'},{k:'b',t:'Vì khách Việt Nam chuộng thực dụng hơn là thẩm mỹ'},
             {k:'c',t:'Vì phim đẹp dễ bị đối thủ sao chép lại nhanh chóng'},{k:'d',t:'Vì người xem nhớ cái đẹp mà không nhớ lý do chọn thương hiệu'}],
    answer:'d', why:{a:'Chi phí không phải lý do chính; nhiều ý đẹp rẻ vẫn lạc.',
      b:'Khái quát sai; khách vẫn đáp ứng tốt với cái đẹp có lý do.',
      c:'Sao chép là rủi ro chung, không riêng gì cái đẹp.',
      d:'Đúng. Đẹp mà không nối về insight thì không để lại lý do mua.'} },
  { type:'mcq', stem:'Insight đã được thử "đúng quá" 70%, nhưng phim làm ra lại được chấm thấp. Nên nghi chỗ nào trước?',
    options:[{k:'a',t:'Insight sai, vì phép thử bằng lời không bao giờ đáng tin'},{k:'b',t:'Cây cầu: vai trò thương hiệu hoặc ý tưởng không bám phần "nhưng"'},
             {k:'c',t:'Kênh chạy sai vì khách mục tiêu không xem mạng xã hội đó'},{k:'d',t:'Ngân sách quá ít nên phim không đủ tần suất để người xem nhớ'}],
    answer:'b', why:{a:'Phép thử đã cho kết quả rõ; bỏ insight là bỏ phần đã chắc.',
      b:'Đúng. Khi gốc chắc mà ngọn hỏng, lỗi thường nằm ở bước chuyển từ insight sang ý tưởng.',
      c:'Điểm chấm thấp đến từ người xem thử, không liên quan kênh.',
      d:'Tần suất ảnh hưởng ghi nhớ khi chạy thật, không phải điểm chấm phim.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kh04-05', skill:'insight', read:'7 phút', t:'Sĩ diện, ngại từ chối, lo cho con — insight Việt nằm ở đâu?',
  situation:'Một hãng bảo hiểm nhân thọ thấy khách tìm hiểu rất nhiều nhưng ít ký. Khảo sát nói lý do là "phí cao". Một tư vấn viên lâu năm lại kể khác: khách thường đồng ý khi người quen giới thiệu, dù không cần; còn khi tự tìm hiểu thì hay hẹn "để bàn với nhà" rồi im luôn.',
  concept:{ name:'Insight từ quy tắc ứng xử Việt',
    body:'Nhiều căng thẳng của khách Việt không nằm ở sản phẩm mà ở <b>quan hệ</b>: giữ thể diện, ngại từ chối thẳng, lo cho con hơn lo cho mình, sợ bị coi là "trù ẻo" khi nói chuyện rủi ro. Những điều này ít khi được nói ra trong khảo sát — người ta đưa lý do dễ nói ("phí cao") thay cho lý do thật ("nói chuyện chết chóc thì xui", "không muốn làm mất lòng người quen"). Vì vậy, khi câu trả lời khảo sát quá gọn, hãy tìm quy tắc ứng xử đứng sau.' },
  example:'"Để bàn với nhà" là một cách từ chối không làm mất lòng. Hỏi sâu vài khách đã hẹn rồi im, bạn nghe: "Mua bảo hiểm là như nghĩ tới chuyện mình mất, nói với vợ thấy gở." Insight: "Tôi muốn lo cho con nếu có chuyện, nhưng nói ra chuyện đó trong nhà thì thấy xui." Thông điệp đổi hướng: không nói rủi ro, nói "quỹ học cho con" — một điều bố mẹ tự hào khi kể. Kịch bản tư vấn cũng đổi: không bắt đầu bằng "nếu chẳng may".',
  takeaway:'Lý do khách nói dễ thường che lý do khó nói; tìm quy tắc ứng xử đứng sau câu trả lời.',
  apply:'Nghĩ về một lần bạn từ chối mua gì đó bằng câu "để em xem đã". Trong 60 giây, nói lý do thật và vì sao bạn không nói thẳng.',
  mistakes:['Tin nguyên văn lý do "giá cao" trong khảo sát.','Nói thẳng về rủi ro, bệnh tật trong khi văn hoá kiêng nhắc tới.'],
  q:[
  { type:'mcq', stem:'Đoán trước: câu "để bàn với nhà" của khách thường mang nghĩa gì?',
    options:[{k:'a',t:'Khách thật sự cần vợ hoặc chồng đồng ý trước khi ký hợp đồng'},{k:'b',t:'Khách chê phí cao nhưng ngại nói thẳng với tư vấn viên'},
             {k:'c',t:'Một cách từ chối giữ hoà khí; lý do thật chưa được nói ra'},{k:'d',t:'Khách đang so sánh với một hãng bảo hiểm khác rẻ hơn'}],
    answer:'c', why:{a:'Đôi khi đúng, nhưng tỉ lệ "hẹn rồi im" cao cho thấy phần lớn là từ chối mềm.',
      b:'Giá là lý do dễ nói nhất; nếu vì giá, khách thường nói thẳng hoặc mặc cả.',
      c:'Đúng. Ngại từ chối thẳng là quy tắc ứng xử phổ biến; phải hỏi sâu mới thấy lý do.',
      d:'Có thể, nhưng không có dấu hiệu nào trong tình huống.'} },
  { type:'mcq', stem:'Khảo sát nói "phí cao", tư vấn viên kể chuyện khác. Bạn nên làm gì tiếp?',
    options:[{k:'a',t:'Hạ phí 15% vì khảo sát có mẫu lớn và đáng tin hơn lời kể'},{k:'b',t:'Phỏng vấn sâu vài khách đã hẹn rồi im để tìm lý do khó nói'},
             {k:'c',t:'Tăng hoa hồng để tư vấn viên bám khách chặt hơn sau buổi hẹn'},{k:'d',t:'Chạy thêm một khảo sát khác với câu hỏi chi tiết hơn về giá phí'}],
    answer:'b', why:{a:'Mẫu lớn không sửa được lý do bị che; hạ phí có thể không đổi gì.',
      b:'Đúng. Mâu thuẫn giữa khảo sát và thực tế là dấu hiệu có lý do khó nói.',
      c:'Bám chặt hơn với một khách đang ngại có thể làm họ tránh mặt hơn.',
      d:'Khảo sát tiếp vẫn nhận lại lý do dễ nói.'} },
  { type:'mcq', stem:'Khách đồng ý mua khi người quen giới thiệu dù không cần. Căng thẳng văn hoá nào đứng sau?',
    options:[{k:'a',t:'Ngại từ chối người quen vì sợ mất lòng, mất quan hệ'},{k:'b',t:'Khách tin người quen tư vấn giỏi hơn tư vấn viên chuyên nghiệp'},
             {k:'c',t:'Người quen thường cho giá tốt hơn mua qua kênh chính thức'},{k:'d',t:'Khách thích mua theo đám đông, người khác mua thì mình mua'}],
    answer:'a', why:{a:'Đúng. Mua để giữ quan hệ — một insight thường dẫn tới huỷ hợp đồng về sau.',
      b:'Tình huống nói "dù không cần", tức không phải vì tin tư vấn.',
      c:'Không có dấu hiệu về giá.',
      d:'Đây là bằng chứng xã hội, khác với ngại từ chối một người cụ thể.'} },
  { type:'mcq', stem:'Một hãng sữa cho bà bầu thấy mẹ trẻ ở quê hay mua loại mẹ chồng chọn dù thích loại khác. Insight hợp lý nhất là gì?',
    options:[{k:'a',t:'Mẹ trẻ ở quê ít thông tin nên để mẹ chồng chọn thay mình'},{k:'b',t:'"Tôi muốn chọn cho con, nhưng cãi mẹ chồng thì mất hoà khí"'},
             {k:'c',t:'Mẹ chồng thường là người trả tiền nên được quyền chọn'},{k:'d',t:'Loại mẹ chồng chọn rẻ hơn nên phù hợp thu nhập ở quê'}],
    answer:'b', why:{a:'Giả định mẹ trẻ thiếu thông tin, trái với chi tiết "thích loại khác".',
      b:'Đúng. Căng thẳng giữa mong muốn và việc giữ hoà khí gia đình.',
      c:'Có thể, nhưng tình huống không nói ai trả tiền.',
      d:'Không có dữ kiện về giá.'} },
  { type:'mcq', stem:'Vì sao thông điệp "quỹ học cho con" tốt hơn "nếu chẳng may bạn ra đi" với khách Việt?',
    options:[{k:'a',t:'Vì con số về quỹ học dễ tính toán và so sánh hơn'},{k:'b',t:'Vì luật cấm quảng cáo bảo hiểm nhắc tới cái chết'},
             {k:'c',t:'Vì nó nói điều bố mẹ tự hào kể, không phải điều thấy gở'},{k:'d',t:'Vì người trẻ không quan tâm tới rủi ro sức khoẻ của mình'}],
    answer:'c', why:{a:'Dễ tính là phụ; lý do chính là cảm giác khi nói ra.',
      b:'Không có lệnh cấm như vậy.',
      c:'Đúng. Cùng một sản phẩm, đổi khung sang điều dễ nói trong nhà.',
      d:'Khách ở đây là bố mẹ lo cho con, không phải người trẻ thờ ơ.'} },
  { type:'mcq', stem:'Một quán cà phê thấy khách đi nhóm hay tranh nhau trả tiền rất lâu ở quầy. Ý tưởng nào khai thác đúng insight sĩ diện?',
    options:[{k:'a',t:'Giảm 10% cho hoá đơn nhóm từ bốn người trở lên'},{k:'b',t:'Đặt thêm quầy thu ngân để giảm thời gian chờ thanh toán'},
             {k:'c',t:'Ép chia hoá đơn tự động, mỗi người quét mã tự trả phần mình'},{k:'d',t:'Thẻ "khao trước" mua sẵn để chủ trả thanh toán kín, nhanh, lịch sự'}],
    answer:'d', why:{a:'Giảm giá không chạm chuyện ai là người khao.',
      b:'Giải quyết hàng chờ, bỏ qua lý do người ta tranh trả.',
      c:'Chia tiền tự động làm mất cơ hội "khao" — đi ngược sĩ diện.',
      d:'Đúng. Giữ được thể diện người khao mà không phải giằng co ở quầy.'} },
  { type:'mcq', stem:'Khi nào nên nghi rằng câu trả lời khảo sát đang che một lý do văn hoá?',
    options:[{k:'a',t:'Khi hành vi thật lệch với lý do khách đưa ra trong khảo sát'},{k:'b',t:'Khi mẫu khảo sát dưới 1.000 người nên chưa đủ tin cậy'},
             {k:'c',t:'Khi phần lớn khách chọn cùng một đáp án trong khảo sát'},{k:'d',t:'Khi khảo sát được làm online thay vì phỏng vấn trực tiếp'}],
    answer:'a', why:{a:'Đúng. Nói "phí cao" mà vẫn mua qua người quen với cùng mức phí là dấu hiệu rõ.',
      b:'Mẫu lớn hay nhỏ không sửa được thiên lệch nói lý do dễ nói.',
      c:'Đồng thuận cao có thể thật; dấu hiệu là sự lệch với hành vi.',
      d:'Hình thức ảnh hưởng một phần, nhưng dấu hiệu chính vẫn là hành vi lệch.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kh04-06', skill:'measure', read:'7 phút', t:'Đọc 2.000 bình luận thế nào để ra insight?',
  situation:'Một thương hiệu nồi chiên không dầu có 2.000 bình luận trên Shopee và TikTok trong ba tháng. Bạn thực tập được giao "tổng hợp insight". Bản báo cáo nộp lên là biểu đồ cảm xúc: 80% tích cực, 15% trung tính, 5% tiêu cực, kèm đám mây từ khoá "đẹp", "tiện", "giao nhanh".',
  concept:{ name:'Đọc bình luận: tìm câu lạ, không đếm từ',
    body:'Đếm cảm xúc và từ khoá cho biết khách hài lòng tới đâu, không cho biết <b>vì sao</b>. Insight thường nằm ở những bình luận dài, có chuyện kể, hoặc lặp lại một chi tiết bất ngờ. Cách làm: lọc bình luận trên 20 chữ, đọc kỹ một mẫu, gắn nhãn theo <b>tình huống sử dụng và nỗi lo</b> chứ không theo khen/chê, rồi đếm nhãn nào lặp lại. Một nhãn lạ xuất hiện ở khoảng một phần mười bình luận dài thường đáng giá hơn mọi từ "đẹp".' },
  example:'Lọc được 400 bình luận dài, bạn đọc 200. Một nhãn lặp lại 24 lần: "mua cho bố mẹ, giờ bố tự làm đồ ăn sáng, không phải chờ con". Chiếm 12% mẫu đã đọc. Đằng sau là căng thẳng: con ở xa muốn bố mẹ ăn uống đủ, nhưng không thể nấu hộ mỗi ngày. Đây là hướng mới: nồi chiên như món quà cho bố mẹ, với nút bấm chữ to. Biểu đồ "80% tích cực" không bao giờ cho ra được điều này.',
  takeaway:'Đếm cảm xúc cho biết khách hài lòng; đọc câu lạ lặp lại cho biết vì sao.',
  apply:'Mở trang sản phẩm của một hãng bạn thích, đọc 20 bình luận dài nhất. Nói trong 60 giây một chi tiết lạ lặp lại ít nhất hai lần.',
  mistakes:['Nộp biểu đồ cảm xúc và đám mây từ khoá rồi gọi là insight.','Chỉ đọc bình luận tiêu cực vì nghĩ insight luôn là nỗi đau.'],
  q:[
  { type:'mcq', stem:'Đoán trước: báo cáo "80% tích cực" và đám mây từ khoá thiếu điều gì?',
    options:[{k:'a',t:'Thiếu so sánh với tỉ lệ tích cực của các đối thủ cùng ngành'},{k:'b',t:'Thiếu lý do vì sao khách mua và dùng sản phẩm'},
             {k:'c',t:'Thiếu phân loại theo từng kênh bán Shopee và TikTok riêng'},{k:'d',t:'Thiếu số lượng mẫu đủ lớn, vì 2.000 bình luận là quá ít'}],
    answer:'b', why:{a:'So sánh đối thủ thêm một dữ kiện nữa, vẫn chưa có "vì sao".',
      b:'Đúng. Đếm cảm xúc chỉ đo mức hài lòng, không mở ra động cơ.',
      c:'Tách kênh giúp đọc số tốt hơn nhưng vẫn ở bậc dữ kiện.',
      d:'2.000 bình luận là rất nhiều cho việc tìm insight.'} },
  { type:'mcq', stem:'Bạn có một buổi chiều để làm lại báo cáo. Bạn chọn cách nào?',
    options:[{k:'a',t:'Dùng công cụ AI tạo đám mây từ khoá chi tiết hơn theo từng tháng'},{k:'b',t:'Đọc toàn bộ 2.000 bình luận, kể cả những bình luận chỉ một chữ'},
             {k:'c',t:'Chỉ đọc 100 bình luận tiêu cực vì nỗi đau mới là insight'},{k:'d',t:'Lọc bình luận dài, đọc kỹ một mẫu, gắn nhãn tình huống và nỗi lo'}],
    answer:'d', why:{a:'Từ khoá chi tiết hơn vẫn là đếm từ.',
      b:'Bình luận một chữ ("đẹp") không chứa chuyện kể; đọc hết là phí thời gian.',
      c:'Insight có thể nằm ở bình luận khen — như chuyện mua cho bố mẹ.',
      d:'Đúng. Tập trung vào nơi có chuyện kể, gắn nhãn theo tình huống mới thấy động cơ.'} },
  { type:'calc', stem:'Bạn đọc 250 bình luận dài và thấy nhãn "mua tặng bố mẹ" xuất hiện 30 lần. Nhãn này chiếm bao nhiêu phần trăm mẫu đã đọc?',
    unit:'%', ans:12, tol:0.2, wrong:[[1.5,'SAI_MAU_SO'],[30,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Mẫu là số bình luận đã đọc: 250 (không phải toàn bộ 2.000).','30 ÷ 250 = 0,12 = <b>12%</b>.'] },
  { type:'mcq', stem:'Nên gắn nhãn bình luận theo tiêu chí nào để tìm insight?',
    options:[{k:'a',t:'Theo tình huống sử dụng và nỗi lo của người viết'},{k:'b',t:'Theo mức sao đánh giá từ một đến năm sao của khách'},
             {k:'c',t:'Theo khen hay chê về giá, về chất lượng và về giao hàng'},{k:'d',t:'Theo độ tuổi và giới tính suy ra từ ảnh đại diện của khách'}],
    answer:'a', why:{a:'Đúng. Tình huống và nỗi lo chỉ ra động cơ.',
      b:'Số sao là thước đo hài lòng, không phải động cơ.',
      c:'Khen/chê theo thuộc tính cho biết điểm mạnh yếu sản phẩm, không cho biết vì sao mua.',
      d:'Đoán nhân khẩu từ ảnh vừa sai vừa không cho động cơ.'} },
  { type:'mcq', stem:'Một hãng sữa rửa mặt thấy nhiều bình luận: "mua cho bạn trai, anh ấy không dám tự mua". Căng thẳng nào đáng khai thác?',
    options:[{k:'a',t:'Nữ giới thường mua mỹ phẩm nhiều hơn nam giới ở mọi ngành'},{k:'b',t:'Bạn trai thích quà tặng hơn là tự mua đồ cho bản thân'},
             {k:'c',t:'Sản phẩm đang được bán với giá quá cao so với túi tiền nam'},{k:'d',t:'Nam muốn da sạch, nhưng ngại bị coi là điệu khi tự mua'}],
    answer:'d', why:{a:'Dữ kiện chung, không giải thích chuyện "không dám".',
      b:'Suy diễn không có căn cứ trong bình luận.',
      c:'Không có chi tiết nào nói về giá.',
      d:'Đúng. Chữ "không dám" là manh mối về một căng thẳng sĩ diện.'} },
  { type:'mcq', stem:'Nhãn "mua tặng bố mẹ" chỉ chiếm 12% bình luận dài. Có nên dùng nó không?',
    options:[{k:'a',t:'Không, vì 88% còn lại mới là số đông cần phục vụ'},{k:'b',t:'Có thể: nhãn lạ lặp lại là manh mối, cần thử "đúng quá"'},
             {k:'c',t:'Có, và nên đổi toàn bộ thương hiệu sang dòng quà tặng'},{k:'d',t:'Không, vì bình luận trên sàn thường là do shop tự viết'}],
    answer:'b', why:{a:'Insight không cần đa số; nó cần đủ lớn và chưa ai khai thác.',
      b:'Đúng. Một phần mười là đáng kể; bước tiếp là thử với người trong tệp.',
      c:'Quá tay: một manh mối chưa kiểm chứng không đủ để đổi cả thương hiệu.',
      d:'Có bình luận ảo, nhưng chuyện kể chi tiết lặp lại khó giả đều như vậy.'} },
  { type:'mcq', stem:'Ngoài bình luận dưới sản phẩm, nguồn nào thường cho insight tốt hơn?',
    options:[{k:'a',t:'Lượt thích và lượt chia sẻ trên bài đăng của fanpage'},{k:'b',t:'Số lượt tìm kiếm từ khoá sản phẩm trên Google mỗi tháng'},
             {k:'c',t:'Câu hỏi khách đăng trong nhóm Facebook trước khi mua'},{k:'d',t:'Bảng xếp hạng bán chạy của ngành hàng trên sàn thương mại'}],
    answer:'c', why:{a:'Lượt thích là số, không có chuyện kể.',
      b:'Lượt tìm kiếm đo nhu cầu, không cho biết nỗi lo.',
      c:'Đúng. Câu hỏi trước khi mua lộ ra nỗi lo và tình huống thật bằng lời của khách.',
      d:'Bảng xếp hạng là dữ kiện thị trường.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kh04-07', skill:'insight', read:'6 phút', t:'Mẹ mua, con dùng — insight của ai?',
  situation:'Một hãng bàn chải điện trẻ em làm quảng cáo nhắm các bé: nhân vật hoạt hình, nhạc vui, "đánh răng như chơi". Bé nào xem cũng thích, nhưng doanh số không nhúc nhích. Chị trưởng nhóm hỏi lại: người rút ví là ai, và họ đang lo điều gì mỗi tối lúc đánh răng cho con?',
  concept:{ name:'Tách insight người mua và người dùng',
    body:'Khi người mua khác người dùng, có <b>hai căng thẳng khác nhau</b>. Người dùng (bé) muốn vui, không muốn bị ép. Người mua (bố mẹ) có nỗi lo riêng: con có đánh đủ sạch không, tối nào cũng phải dỗ dành, và cả cảm giác bất lực. Quảng cáo chỉ chạm người dùng thì tạo mong muốn nhưng không tạo quyết định; chỉ chạm người mua thì dễ mua một lần rồi bỏ xó vì bé không chịu dùng. Cần biết ai quyết, ai giữ thói quen, và nói với mỗi người điều họ cần nghe.' },
  example:'Hỏi các mẹ, bạn nghe: "Tôi muốn con tự giác đánh răng, nhưng tối nào cũng phải canh, mệt và hay to tiếng." Đó là insight người mua. Insight người dùng: bé thích được tự làm như người lớn. Thông điệp mới cho mẹ: "Hai phút tự đánh, mẹ khỏi canh" — máy tự đếm giờ, đèn báo khi đủ sạch. Nhân vật hoạt hình vẫn giữ trên bao bì và trong app cho bé. Hai insight, hai lớp thông điệp, một sản phẩm.',
  takeaway:'Người mua và người dùng khác nhau thì có hai insight; quảng cáo phải biết đang nói với ai.',
  apply:'Chọn một sản phẩm mà người mua khác người dùng (quà tặng, đồ trẻ em, phần mềm công ty). Nói trong 60 giây: mỗi bên đang lo điều gì.',
  mistakes:['Chỉ làm quảng cáo cho người dùng vì họ vui vẻ, dễ quay.','Gộp hai người thành một chân dung khách chung chung.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao quảng cáo làm bé thích mà doanh số không tăng?',
    options:[{k:'a',t:'Bé chưa đủ tuổi nên không hiểu hết thông điệp quảng cáo'},{k:'b',t:'Nhạc và hình vui nhưng thiếu thông tin về tính năng kỹ thuật'},
             {k:'c',t:'Giá bàn chải điện quá cao so với thu nhập các gia đình trẻ'},{k:'d',t:'Người quyết mua là bố mẹ, và nỗi lo của họ chưa được chạm'}],
    answer:'d', why:{a:'Bé hiểu và thích; vấn đề là bé không trả tiền.',
      b:'Thêm tính năng cũng chưa chạm nỗi lo của mẹ nếu không gắn với nó.',
      c:'Không có dữ kiện về giá trong tình huống.',
      d:'Đúng. Quảng cáo tạo mong muốn ở người dùng nhưng không chạm người ra quyết định.'} },
  { type:'mcq', stem:'Bạn được sửa quảng cáo. Bạn chọn hướng nào?',
    options:[{k:'a',t:'Thông điệp cho mẹ "mẹ khỏi canh", giữ nhân vật vui cho bé'},{k:'b',t:'Bỏ hẳn nhân vật hoạt hình, chuyển sang phong cách y khoa nghiêm túc'},
             {k:'c',t:'Tăng tần suất quảng cáo cho bé để bé đòi bố mẹ mua nhiều hơn'},{k:'d',t:'Đưa bác sĩ nha khoa ra nói về tỉ lệ sâu răng trẻ em tại Việt Nam'}],
    answer:'a', why:{a:'Đúng. Mỗi lớp thông điệp nói với đúng người, đúng căng thẳng.',
      b:'Bỏ nhân vật làm mất lý do để bé chịu dùng — mua rồi bỏ xó.',
      c:'Dựa vào bé đòi là đẩy căng thẳng sang cho bố mẹ, dễ phản tác dụng.',
      d:'Nói sâu răng là điều hiển nhiên; mẹ biết rồi, cái mẹ mệt là việc canh mỗi tối.'} },
  { type:'mcq', stem:'Một phần mềm chấm công bán cho công ty: giám đốc nhân sự mua, nhân viên dùng. Insight người dùng nào quan trọng để tránh bị bỏ?',
    options:[{k:'a',t:'Giám đốc muốn giảm chi phí nhân sự cho bộ phận hành chính'},{k:'b',t:'Nhân viên muốn chấm công nhanh, nhưng sợ bị theo dõi'},
             {k:'c',t:'Công ty cần báo cáo đẹp để trình bày với ban lãnh đạo'},{k:'d',t:'Kế toán muốn xuất số liệu lương vào Excel nhanh hơn'}],
    answer:'b', why:{a:'Đây là insight người mua, không phải người dùng.',
      b:'Đúng. Nếu nhân viên thấy bị soi, họ lách, và phần mềm bị bỏ dù đã mua.',
      c:'Nhu cầu tổ chức, không phải căng thẳng của người dùng hằng ngày.',
      d:'Một người dùng phụ; nhóm đông nhất là nhân viên chấm công.'} },
  { type:'mcq', stem:'Rủi ro nếu chỉ chạm insight người mua mà bỏ người dùng là gì?',
    options:[{k:'a',t:'Người mua sẽ thấy quảng cáo quá nghiêm túc và khô khan'},{k:'b',t:'Chi phí quảng cáo tăng vì phải nhắm hai nhóm cùng lúc'},
             {k:'c',t:'Mua được lần đầu nhưng người dùng bỏ, không mua lại'},{k:'d',t:'Đối thủ sẽ dễ dàng chiếm được nhóm người dùng còn bỏ trống'}],
    answer:'c', why:{a:'Giọng quảng cáo là chuyện thực thi, không phải rủi ro chính.',
      b:'Tình huống là bỏ người dùng, tức chỉ nhắm một nhóm.',
      c:'Đúng. Bé không chịu dùng thì bàn chải bỏ xó, mẹ không mua đầu thay thế.',
      d:'Có thể xảy ra, nhưng hệ quả trực tiếp là mất mua lại.'} },
  { type:'mcq', stem:'Một hãng thức ăn cho mèo: chủ mua, mèo ăn. Insight người mua nào dễ tạo quyết định nhất?',
    options:[{k:'a',t:'Mèo thích vị cá ngừ hơn vị gà theo khảo sát của hãng'},{k:'b',t:'Thức ăn hạt khô giúp mèo có bộ lông bóng mượt hơn'},
             {k:'c',t:'"Tôi muốn mèo ăn ngon, nhưng sợ đổi hạt mèo bỏ ăn thì phí cả túi"'},{k:'d',t:'Chủ mèo trẻ thích bao bì dễ thương để chụp ảnh đăng mạng'}],
    answer:'c', why:{a:'Sở thích người dùng (mèo), không phải căng thẳng của người mua.',
      b:'Lợi ích sản phẩm mà hãng nào cũng nói.',
      c:'Đúng. Nỗi sợ phí tiền khi đổi hạt gợi ý túi thử nhỏ hoặc cam kết đổi trả.',
      d:'Có thể đúng một phần, nhưng yếu hơn nỗi lo phí tiền khi đổi hạt.'} },
  { type:'mcq', stem:'Làm sao biết ai là người quyết mua khi chưa rõ?',
    options:[{k:'a',t:'Hỏi ai trả tiền và ai có quyền nói "không" ở quầy'},{k:'b',t:'Mặc định người dùng là người quyết vì họ hiểu sản phẩm nhất'},
             {k:'c',t:'Xem nhóm nào tương tác nhiều nhất với fanpage thương hiệu'},{k:'d',t:'Chọn nhóm đông hơn trong hai nhóm theo dữ liệu khảo sát'}],
    answer:'a', why:{a:'Đúng. Người trả tiền và người có quyền phủ quyết là người phải được thuyết phục.',
      b:'Người dùng hiểu sản phẩm nhưng không phải lúc nào cũng quyết.',
      c:'Tương tác cho biết ai thích nội dung, không cho biết ai rút ví.',
      d:'Đông không có nghĩa là có quyền quyết.'} },
  { type:'mcq', stem:'Một hãng xe đạp trẻ em có hai insight: bé muốn "đi xe như anh lớn", mẹ "sợ con ngã trên đường". Kênh nào hợp để nói insight của mẹ?',
    options:[{k:'a',t:'Hoạt hình ngắn trên kênh YouTube thiếu nhi buổi chiều'},{k:'b',t:'Sticker và đồ chơi tặng kèm trong hộp khi mua xe đạp'},
             {k:'c',t:'Hội nhóm phụ huynh và trang so sánh an toàn trước khi mua'},{k:'d',t:'Biển quảng cáo lớn ở cổng trường mầm non vào giờ tan học'}],
    answer:'c', why:{a:'Đây là kênh của bé.',
      b:'Đồ tặng kèm hợp với bé và xảy ra sau khi đã mua.',
      c:'Đúng. Mẹ tìm hiểu về an toàn ở hội nhóm và trang so sánh, đúng lúc ra quyết định.',
      d:'Tiếp cận cả hai nhưng quá ngắn để nói chuyện an toàn.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kh04-08', skill:'brand', read:'6 phút', t:'Insight từng đúng, sao giờ quảng cáo hết chạm?',
  situation:'Một hãng mì gói từng thắng lớn với insight "sinh viên xa nhà nhớ bữa cơm mẹ nấu". Năm năm sau, chiến dịch tương tự được chạy lại nhưng lượt xem hết phim giảm một nửa và bình luận chỉ còn "cũ rồi". Sếp muốn làm phần hai "cho quen thuộc".',
  concept:{ name:'Insight có hạn dùng',
    body:'Insight dựa trên một hoàn cảnh sống. Khi hoàn cảnh đổi, căng thẳng cũng đổi, và insight <b>hết hạn</b>. Có ba dấu hiệu: hành vi nền đã khác (người ta không còn làm việc đó), căng thẳng đã được giải (có cách khác gỡ nó rồi), hoặc câu đã bị nói quá nhiều nên thành hiển nhiên. Giữ được tinh thần gốc thì tốt, nhưng phải kiểm lại phần "nhưng" trong đời sống hiện tại, không phải trong trí nhớ về chiến dịch cũ.' },
  example:'Sinh viên bây giờ gọi video với mẹ hằng ngày, đặt đồ ăn qua app, nhiều bạn học gần nhà. Nỗi nhớ cơm mẹ vẫn có, nhưng không còn là vướng mắc lớn. Hỏi lại, bạn nghe: "Tôi muốn tự lo được bữa ăn, nhưng ngán đồ giao, lại không biết nấu." Insight mới giữ tinh thần "bữa ăn như ở nhà" nhưng đổi phần "nhưng": từ nhớ mẹ sang tự lập. Phần hai sẽ là công thức mì năm phút giống món mẹ nấu, không phải thêm một phim nhớ nhà.',
  takeaway:'Insight gắn với hoàn cảnh sống; hoàn cảnh đổi thì phải kiểm lại phần "nhưng".',
  apply:'Nhớ một quảng cáo bạn thích cách đây vài năm. Nói trong 60 giây: căng thẳng của nó còn đúng hôm nay không, và điều gì đã đổi.',
  mistakes:['Làm phần hai vì chiến dịch cũ từng thắng.','Kết luận insight hết hạn chỉ vì một đợt chạy kém mà không hỏi lại khách.'],
  q:[
  { type:'mcq', stem:'Đoán trước: lý do nào có khả năng nhất khiến chiến dịch cũ hết chạm?',
    options:[{k:'a',t:'Phim cũ có chất lượng hình ảnh thấp so với tiêu chuẩn hiện nay'},{k:'b',t:'Đời sống sinh viên đã đổi nên căng thẳng cũ không còn lớn'},
             {k:'c',t:'Ngân sách phân phối quá thấp nên phim không đến được khách'},{k:'d',t:'Sinh viên bây giờ không còn ăn mì gói như các thế hệ trước'}],
    answer:'b', why:{a:'Hình ảnh cũ ảnh hưởng một phần, nhưng bình luận "cũ rồi" nói về ý chứ không về hình.',
      b:'Đúng. Gọi video, app đồ ăn đã làm nỗi nhớ cơm mẹ bớt gắt.',
      c:'Lượt xem hết giảm là chuyện phản ứng của người đã xem, không phải chuyện tiếp cận.',
      d:'Sinh viên vẫn ăn mì; cái đổi là hoàn cảnh quanh bữa ăn.'} },
  { type:'mcq', stem:'Sếp muốn làm phần hai "cho quen thuộc". Bạn đề xuất gì?',
    options:[{k:'a',t:'Làm phần hai như sếp muốn, nhưng thay diễn viên trẻ hơn'},{k:'b',t:'Bỏ hẳn tinh thần "bữa ăn như ở nhà" và làm một ý mới hoàn toàn'},
             {k:'c',t:'Chạy lại phim cũ với ngân sách gấp đôi để khơi lại hoài niệm'},{k:'d',t:'Giữ tinh thần gốc, kiểm lại phần "nhưng" với sinh viên hôm nay'}],
    answer:'d', why:{a:'Đổi diễn viên không cứu một căng thẳng đã phai.',
      b:'Tinh thần gốc vẫn là tài sản thương hiệu; bỏ hẳn là phí.',
      c:'Gấp đôi tiền cho một ý người xem đã nói "cũ rồi" là lãng phí.',
      d:'Đúng. Giữ tài sản, cập nhật vướng mắc theo đời sống hiện tại.'} },
  { type:'mcq', stem:'Dấu hiệu nào cho thấy một insight đã hết hạn?',
    options:[{k:'a',t:'Khách vẫn gật đầu nhưng nói "biết rồi", không ai kể chuyện nhà mình'},{k:'b',t:'Chiến dịch đã chạy liên tục hơn sáu tháng mà không đổi phim'},
             {k:'c',t:'Đối thủ bắt đầu dùng một insight khác hẳn với mình'},{k:'d',t:'Ngân sách năm nay bị cắt nên phải chọn ý rẻ hơn'}],
    answer:'a', why:{a:'Đúng. Từ "đúng quá" rơi xuống "biết rồi" là insight đã thành hiển nhiên.',
      b:'Chạy lâu có thể gây mòn quảng cáo, nhưng đó là chuyện phim, không phải insight.',
      c:'Đối thủ đổi hướng không nói gì về insight của bạn.',
      d:'Ngân sách không liên quan tới độ đúng của insight.'} },
  { type:'mcq', stem:'Một hãng ví điện tử có insight "ngại cầm tiền mặt vì sợ mất". Nay ai cũng quét mã. Điều gì xảy ra với insight này?',
    options:[{k:'a',t:'Vẫn đúng, vì nỗi sợ mất tiền là cảm xúc không bao giờ đổi'},{k:'b',t:'Đúng hơn trước, vì tiền điện tử càng phổ biến thì càng sợ mất'},
             {k:'c',t:'Chỉ cần đổi hình ảnh sang người trẻ là insight dùng lại được'},{k:'d',t:'Căng thẳng đã được giải; cần tìm vướng mắc mới khi đã quét mã'}],
    answer:'d', why:{a:'Nỗi sợ còn, nhưng cái vướng cụ thể (cầm tiền mặt) đã không còn.',
      b:'Suy diễn ngược; khách không còn cầm tiền mặt nên câu không còn vướng.',
      c:'Đổi hình ảnh không làm căng thẳng cũ sống lại.',
      d:'Đúng. Khi vướng đã được gỡ, thương hiệu phải tìm "nhưng" mới, ví dụ lo lộ thông tin.'} },
  { type:'mcq', stem:'Vì sao không nên kết luận insight hết hạn chỉ từ một đợt chạy kém?',
    options:[{k:'a',t:'Vì insight tốt thì đúng mãi và không bao giờ hết hạn'},{k:'b',t:'Vì kém có thể do phim, kênh hay thời điểm, không do insight'},
             {k:'c',t:'Vì một đợt chạy chưa đủ ngân sách để kết luận thống kê'},{k:'d',t:'Vì sếp đã duyệt insight nên không thể đổi giữa chừng'}],
    answer:'b', why:{a:'Insight có hạn dùng — đó là nội dung bài.',
      b:'Đúng. Phải hỏi lại khách để tách lỗi insight khỏi lỗi thực thi.',
      c:'Ngân sách có thể là lý do, nhưng quan trọng hơn là có nhiều nguồn gây kém.',
      d:'Sếp duyệt không làm insight đúng hơn.'} },
  { type:'mcq', stem:'Cách nào giúp phát hiện insight sắp hết hạn sớm nhất?',
    options:[{k:'a',t:'Chờ báo cáo doanh số quý để thấy xu hướng giảm rõ ràng'},{k:'b',t:'Theo dõi số lượt thích trên fanpage theo từng tháng'},
             {k:'c',t:'Định kỳ đọc lại câu insight cho khách và nghe phản ứng'},{k:'d',t:'Thuê hãng nghiên cứu làm khảo sát lớn mỗi năm một lần'}],
    answer:'c', why:{a:'Doanh số tụt là tín hiệu muộn; lúc đó đã mất nhiều.',
      b:'Lượt thích bị ảnh hưởng bởi quá nhiều thứ ngoài insight.',
      c:'Đúng. Phép thử "đúng quá" rẻ, nhanh, và bắt được lúc câu chuyển sang "biết rồi".',
      d:'Khảo sát lớn một năm một lần là quá thưa và khó bắt cảm xúc.'} },
  { type:'mcq', stem:'Một thương hiệu cà phê từng dùng "cà phê sáng cho người chạy deadline". Nay nhiều người làm việc tại nhà. Hướng cập nhật nào hợp lý?',
    options:[{k:'a',t:'"Muốn tách việc với nhà, nhưng làm tại nhà thì cả ngày lẫn lộn"'},{k:'b',t:'Giữ nguyên thông điệp vì deadline thì ở đâu cũng có cả'},
             {k:'c',t:'Chuyển sang quảng cáo giao cà phê tận nhà nhanh trong 15 phút'},{k:'d',t:'Tập trung vào nhóm vẫn đi làm văn phòng, bỏ nhóm làm tại nhà'}],
    answer:'a', why:{a:'Đúng. Vướng mắc mới của người làm tại nhà; cà phê có thể là nghi thức "bắt đầu làm việc".',
      b:'Deadline vẫn có, nhưng không còn là căng thẳng riêng của hoàn cảnh mới.',
      c:'Giao nhanh là tính năng dịch vụ, không phải insight.',
      d:'Bỏ một nhóm đang lớn lên chỉ vì insight cũ không hợp với họ.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:kh04-09', skill:'comm', read:'7 phút', t:'Viết câu insight thế nào để cả nhóm dùng được?',
  situation:'Bạn cần gửi brief cho agency về một dòng nước uống bổ sung điện giải cho người lao động ngoài trời. Bản nháp insight đang dài năm dòng: vừa số liệu nhiệt độ, vừa tỉ lệ mất nước, vừa lời kể của thợ xây, vừa lợi ích sản phẩm. Agency trả lời: "Chưa rõ bọn em cần bám vào đâu."',
  concept:{ name:'Câu insight bốn phần',
    body:'Một câu insight dùng được thường có bốn phần: <b>ai</b> (cụ thể, không phải "mọi người"), <b>muốn gì</b>, <b>nhưng vướng gì</b>, và nói bằng <b>giọng của khách</b>, như họ tự nói. Không chứa tên sản phẩm, không chứa số liệu thị trường — những thứ đó để ở phần bối cảnh của brief. Một câu, đọc to trong một hơi. Nếu agency đọc xong mà hình dung được một người thật đang khó xử, câu đó làm xong việc.' },
  example:'Bản năm dòng có đủ thông tin nhưng không có một người. Viết lại: "Thợ xây làm trưa hè: Tôi biết phải uống nước, nhưng uống nhiều thì bụng óc ách, leo giàn khó, mà uống ít thì chiều nào cũng lả." Ai: thợ xây trưa hè. Muốn: đủ sức cả ngày. Vướng: uống nước thường thì đầy bụng. Giọng: như chính họ nói ở lán. Số liệu nhiệt độ và lợi ích điện giải chuyển xuống phần bối cảnh. Agency đọc và hỏi ngay: "Vậy một ngụm là đủ?" — đúng hướng ý tưởng.',
  takeaway:'Một câu, một người, một mong muốn, một vướng mắc, bằng giọng của khách — không có tên sản phẩm.',
  apply:'Viết lại insight bạn đang dùng thành một câu bốn phần. Đọc to cho một người ngoài ngành nghe, hỏi họ hình dung ra ai.',
  mistakes:['Nhét số liệu và lợi ích sản phẩm vào câu insight.','Viết bằng giọng báo cáo thay vì giọng của người khách.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao agency không biết bám vào đâu trong bản insight năm dòng?',
    options:[{k:'a',t:'Vì bản nháp thiếu số liệu thị trường để agency tin tưởng'},{k:'b',t:'Vì agency chưa từng làm cho ngành đồ uống nên chưa quen'},
             {k:'c',t:'Vì nó trộn quá nhiều thứ, không hiện ra một người đang khó xử'},{k:'d',t:'Vì bản nháp viết bằng tiếng Việt, cần thêm bản tiếng Anh'}],
    answer:'c', why:{a:'Bản nháp đã có nhiều số; thêm số làm rối hơn.',
      b:'Agency giỏi vẫn cần một điểm bám rõ; lỗi nằm ở brief.',
      c:'Đúng. Đủ thông tin nhưng không có tiêu điểm — không có một con người để hình dung.',
      d:'Ngôn ngữ không phải vấn đề.'} },
  { type:'mcq', stem:'Bạn sửa bản insight năm dòng thế nào trước khi gửi lại?',
    options:[{k:'a',t:'Giữ nguyên nội dung, in đậm câu quan trọng nhất để agency thấy'},{k:'b',t:'Thêm một đoạn giải thích lợi ích điện giải của sản phẩm cho rõ'},
             {k:'c',t:'Cắt còn hai dòng bằng cách bỏ lời kể thợ xây, giữ lại số liệu'},{k:'d',t:'Viết một câu: ai, muốn gì, vướng gì, bằng giọng thợ xây'}],
    answer:'d', why:{a:'In đậm không giải quyết việc trộn nhiều loại thông tin.',
      b:'Lợi ích sản phẩm không thuộc câu insight.',
      c:'Bỏ lời kể là bỏ đúng phần sống nhất.',
      d:'Đúng. Câu bốn phần cho agency một người để hình dung; số liệu chuyển xuống bối cảnh.'} },
  { type:'mcq', stem:'Câu nào đúng khuôn câu insight bốn phần?',
    options:[{k:'a',t:'"Tài xế công nghệ: Tôi muốn chạy thêm cuốc tối, nhưng về khuya sợ vợ con lo"'},{k:'b',t:'"72% tài xế công nghệ chạy hơn 10 tiếng mỗi ngày tại TP.HCM"'},
             {k:'c',t:'"Tài xế cần nước tăng lực X để tỉnh táo khi chạy xe ban đêm"'},{k:'d',t:'"Mọi người đều muốn kiếm thêm thu nhập trong thời buổi khó khăn"'}],
    answer:'a', why:{a:'Đúng. Có ai, muốn gì, vướng gì, giọng của khách.',
      b:'Đây là số liệu bối cảnh, không phải insight.',
      c:'Có tên sản phẩm, và là lời hứa của hãng, không phải căng thẳng của khách.',
      d:'"Mọi người" và mong muốn hiển nhiên, không có vướng mắc.'} },
  { type:'mcq', stem:'Vì sao không nên để tên sản phẩm trong câu insight?',
    options:[{k:'a',t:'Vì tên sản phẩm có thể bị đổi trước khi chiến dịch lên sóng'},{k:'b',t:'Vì insight là sự thật của khách, có trước sản phẩm'},
             {k:'c',t:'Vì agency sẽ lạm dụng tên sản phẩm trong mọi ý tưởng'},{k:'d',t:'Vì luật quảng cáo cấm nêu tên sản phẩm trong tài liệu brief'}],
    answer:'b', why:{a:'Đổi tên là chuyện hiếm và không phải lý do chính.',
      b:'Đúng. Có tên sản phẩm là câu đã chuyển thành lời hứa, không còn là điều khách tự nói.',
      c:'Không có lý do để nghĩ agency sẽ làm vậy.',
      d:'Không có quy định như vậy cho tài liệu nội bộ.'} },
  { type:'mcq', stem:'Một hãng dầu gội viết: "Phụ nữ hiện đại muốn tóc đẹp và tự tin." Nên sửa phần nào trước?',
    options:[{k:'a',t:'Thêm vế vướng mắc cụ thể và viết bằng giọng của một người thật'},{k:'b',t:'Thay "phụ nữ hiện đại" bằng "phụ nữ 25–35 tuổi ở thành phố lớn"'},
             {k:'c',t:'Thêm số liệu về tỉ lệ rụng tóc để câu insight thuyết phục hơn'},{k:'d',t:'Rút ngắn còn "muốn tóc đẹp" cho súc tích, dễ nhớ và dễ in'}],
    answer:'a', why:{a:'Đúng. Thiếu nhất là phần "nhưng" và giọng khách; không có chúng thì chỉ là câu hiển nhiên.',
      b:'Cụ thể hơn về ai là tốt, nhưng câu vẫn không có căng thẳng.',
      c:'Số liệu thuộc bối cảnh, không làm câu chạm hơn.',
      d:'Ngắn hơn nhưng vẫn hiển nhiên.'} },
  { type:'mcq', stem:'Làm sao kiểm tra nhanh câu insight đã viết ổn cho agency dùng?',
    options:[{k:'a',t:'Đếm xem câu có dưới 20 chữ và có đủ số liệu dẫn chứng không'},{k:'b',t:'Gửi sếp duyệt trước, vì sếp hiểu thương hiệu nhất công ty'},
             {k:'c',t:'Đọc cho người ngoài ngành nghe, hỏi họ hình dung ra ai'},{k:'d',t:'So với câu insight của đối thủ để chắc không bị trùng ý'}],
    answer:'c', why:{a:'Độ dài chỉ là gợi ý; số liệu không thuộc câu insight.',
      b:'Sếp hiểu thương hiệu nhưng không phải người cần hình dung khách.',
      c:'Đúng. Nếu người ngoài hình dung được một người đang khó xử, agency cũng sẽ vậy.',
      d:'Không trùng là tốt, nhưng không cho biết câu có dùng được không.'} },
  { type:'mcq', stem:'Số liệu nhiệt độ và tỉ lệ mất nước nên đặt ở đâu trong brief?',
    options:[{k:'a',t:'Ngay trong câu insight để agency thấy vấn đề nghiêm trọng'},{k:'b',t:'Bỏ hẳn, vì agency chỉ cần insight là đủ để làm việc'},
             {k:'c',t:'Ở phần tiêu đề brief cho agency đọc ngay từ dòng đầu'},{k:'d',t:'Ở phần bối cảnh, làm bằng chứng đỡ cho câu insight'}],
    answer:'d', why:{a:'Nhồi số vào câu insight làm mất giọng của khách.',
      b:'Số liệu vẫn có ích để agency hiểu quy mô và độ tin; chỉ cần đặt đúng chỗ.',
      c:'Tiêu đề nên là vấn đề kinh doanh, không phải số liệu vật lý.',
      d:'Đúng. Bối cảnh giữ số liệu, câu insight giữ con người.'} }
  ] }

] });
